package cli

import (
	"bytes"
	"strings"
	"testing"
)

// TestAnalyseExplicitAllSkippedInputReportsDiagnostic verifies that scanning only a generated file reports a diagnostic and exits 2.
//
// Without it, a user who scans a skipped file directly could read a clean zero-file report as a pass.
func TestAnalyseExplicitAllSkippedInputReportsDiagnostic(t *testing.T) {
	root := t.TempDir()
	// The generated-code header is what makes discovery skip this file before parsing.
	writeFile(t, root, "generated.go", "// Code generated by fixture. DO NOT EDIT.\npackage generated\n")
	t.Chdir(root)

	var out, errOut bytes.Buffer
	code := Main([]string{"analyse", "--format", "text", "generated.go"}, &out, &errOut)
	if code != 2 {
		t.Fatalf("exit = %d, want 2\nstderr:\n%s\nstdout:\n%s", code, errOut.String(), out.String())
	}
	// The skip is reported in the text report on stdout, not as an error on stderr.
	if errOut.Len() != 0 {
		t.Fatalf("stderr = %q, want empty", errOut.String())
	}
	output := out.String()
	// The --include-ignored hint tells the user how to get a real scan of the file they named.
	for _, want := range []string{
		"explicit input skipped before parsing",
		"source=generated",
		"--include-ignored",
		"exit: 2",
	} {
		if !strings.Contains(output, want) {
			t.Fatalf("output missing %q:\n%s", want, output)
		}
	}
}
